def generar(modelo, tokenizador, prompt, max_tokens=50):
    ids = tokenizador.encode(prompt)          # texto -> tokens
    for _ in range(max_tokens):
        probs = modelo.predecir_siguiente(ids)  # distribución sobre el vocabulario
        siguiente = muestrear(probs)           # p. ej. con temperatura o top-p
        ids.append(siguiente)                  # el nuevo token pasa a formar parte del contexto
        if siguiente == tokenizador.fin_de_texto:
            break
    return tokenizador.decode(ids)

